export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11H5V10m4 11v-7h6v7',task:'M8 4H5v17h14V4h-3M9 3h6v4H9zM8 12h8M8 16h6',file:'M14 3H5v18h14V8zM14 3v6h5M8 13h8M8 17h6',user:'M20 21a8 8 0 0 0-16 0M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8',bell:'M18 8a6 6 0 0 0-12 0c0 6-3 6-3 9h18c0-3-3-3-3-9M10 21h4',arrow:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',phone:'M7 3H3c-1 10 8 19 18 18v-5l-5-2-3 3-6-6 3-3z',box:'m3 7 9-4 9 4v11l-9 4-9-4zM3 7l9 5 9-5M12 12v10',calendar:'M3 6h18v15H3zM7 3v6M17 3v6M3 11h18',check:'m4 12 5 5L20 6',camera:'M3 7h5l2-3h4l2 3h5v14H3zM16 13a4 4 0 1 0-8 0 4 4 0 0 0 8 0',search:'M16 16l5 5M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',tool:'m3 21 9-9M21 3l-6 2-2 5 3 3 5-2z'};
export const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.file}"/></svg>`;
export const tag=s=>`<span class="tag ${s==='已完成'?'green':/待|未/.test(s)?'amber':'blue'}">${esc(s)}</span>`;
export const categoryLabel=code=>{const c=String(code??'');const dict=(()=>{try{const d=JSON.parse(localStorage.getItem('ecinfo_dict_data')||'{}');return d['Call類型']||d['報價類別']||[];}catch{return [];}})();const hit=dict.find(x=>x.code===c||x.name===c);return hit?.name||c;};
export const note=t=>`<div class="notice">${esc(t)}</div>`;
export const empty=(t='暫無符合條件的記錄')=>`<div class="empty">${icon('search')}<h3>${t}</h3><p>可調整篩選條件或清除搜尋內容。</p></div>`;
export const button=(t,a,cls='primary')=>`<button type="button" class="${cls}" data-action="${a}">${t}</button>`;
export const link=(t,path,cls='')=>`<a class="${cls}" href="#/${path}">${t}</a>`;
export const heading=(t,sub='')=>`<div class="section-title"><h2>${t}</h2>${sub}</div>`;
export const field=(k,v)=>`<div class="data-row"><span>${esc(k)}</span><strong>${esc(v||'待補')}</strong></div>`;
export function card(t,section='tasks'){return `<a class="task-card" href="#/${section}/${encodeURIComponent(t.id)}"><div class="card-top"><span class="category">${esc(categoryLabel(t.category))}</span><span class="serial">${esc(t.id)}</span>${icon('arrow')}</div><h3>${esc(t.customer)}</h3><p class="contract">合約 ${esc(t.contractNo)}</p><p class="description">${esc(t.desc)}</p><div class="card-bottom">${tag(t.status)}<span>${esc(t.schedule?.slice(11)||'時間待安排')} · ${esc(t.master||'待安排師傅')}</span></div></a>`;}
